function StrengthDialog:Awake()
    self.buyHpLimit = checkInt(CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 16).num)
    ---@type StoreComponent
    local storeComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.StoreComponent)
    local count = 0
    if storeComp then
        count = storeComp:GetMothCardBuyTimesCount()
    end
    self.__everythingChangeHandler = Bind(self, self.ChangeStrength)
    self.buyHpLimit = self.buyHpLimit + count
    Events.AddListener(Constants.EventNames.EveryThingChangeEventName, self.__everythingChangeHandler)
    SetButtonAction(self.BtnClose.gameObject, function()
        --UIModule.CloseDialog(self.controller)
        UIModule.BackDialog()
    end)
    SetButtonAction(self.EmptyBg.gameObject, function()
        --UIModule.CloseDialog(self.controller)
        UIModule.BackDialog()
    end)
    SetButtonAction(self.BtnExplain , function ()
        CfUtils.ShowModuleToast(901)
    end)
    ---@type Engine.UI.UIArgument
    local argument = self.controller.Argument
    if argument.parameters then
        if argument.parameters.overrideSorting then
            local _orderTracker = self.controller.gameObject:GetComponent(typeof(CS.Engine.UI.OrderTracker))
            if not IsNull(_orderTracker) then
                self.valueCusOIL = checkInt(argument.parameters.overrideSorting)
                --_orderTracker.addSortingOrder = checkInt(argument.parameters.overrideSorting)
            end
        end
        if argument.parameters.hideBtnMore then
            self.hideBtnMore = true
        end
    end
    self.DiamondButton.gameObject:GetComponent("FontStyleButton"):ResetFontStyle("B3")

    local haveDiamondNum = GoodsUtils.GetThingNo(Constants.Currency.HpExchangeID)
    if haveDiamondNum > 0 then
        ---存在罐头的情况下页签切到罐头
        self._selectIdx = TabType.Good
    end
end

