---OnDiamondExchangeAction
---钻石兑换的按钮事件
---@param eventData UnityEngine.EventSystems.PointerEventData
function StrengthDialog:OnDiamondExchangeAction(eventData)
    local toDiamondExchange = function(consumeId, consumeNum, notEnoughCb, succeedCb)
        local curNum = GoodsUtils.GetThingNo(consumeId)
        if curNum >= consumeNum then
            local requestData = { consume = table.serialize({ goodsId = consumeId, num = consumeNum }) }
            GameUtils.Request(Interfaces.PlayerStrengthHP, requestData, function(request, response)
                if checkNumber(response.errCode) == 0 then
                    local responseData = checkTable(response.data)
                    local rewards = responseData.rewards
                    if isTable(rewards) then
                        table.insert(rewards, { goodsId = consumeId, num = -consumeNum })
                        GoodsUtils.DrawRewards(rewards , true)
                        self.LeftPanel:Play("Success", 0, 0)
                        self.LeftPanel:Update(0)
                        if succeedCb then
                            succeedCb()
                        end
                        self:FreshUI()
                    end
                end
            end, function(exception)
                GameUtils.Toast(exception.Message)
            end)
        else
            if notEnoughCb then
                notEnoughCb()
            end
        end
    end

    if self._selectIdx == TabType.Good then
        local consumeId = Constants.Currency.HpExchangeID
        ---@type ExchangeStrengthVo
        local exchangeStrengthVo = CfUtils.GetCfVo(AutoIds.IdSetting302, "ExchangeStrengthVo", consumeId)
        local consumeNum = checkInt(exchangeStrengthVo.itemIdCost)
        toDiamondExchange(consumeId, consumeNum, function()
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(consumeId)
            GameUtils.Toast(localize("当前所需的_name_不足，不能兑换", { _name_ = vo.name }))
        end)

    else
        ---钻石的情况下兑换
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        local remainNum = self.buyHpLimit - checkNumber(playerComponent.playerDojo.buyHpNum)
        remainNum = remainNum > 0 and remainNum or 0
        if remainNum > 0 then
            ---@type TableML.TableFile
            local tableFile = _settingMgr:Get(AutoIds.IdSetting307)
            local id = math.min(checkNumber(playerComponent.playerDojo.buyHpNum) + 1, self.buyHpLimit)
            ---@type TableML.TableFileRow
            local row = tableFile:FindByPrimaryKey(id)
            if not row then
                return
            end

            local consumeId  = checkInt(row:Get("itemId"))
            local consumeNum = checkInt(row:Get("itemIdCost"))
            toDiamondExchange(consumeId, consumeNum, function()
                if BattleViewMgr then
                    -- 战斗结算界面屏蔽跳转
                    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(consumeId)
                    GameUtils.Toast(localize("当前所需的_name_不足，不能兑换", { _name_ = vo.name }))
                else
                    GoodsUtils.CheckCurrencyConsume({goodsId = consumeId, num = consumeNum}, function()
                        -- 请求兑换的逻辑
                        self:FreshUI()
                    end)
                end
            end, function()
                playerComponent.playerDojo.buyHpNum = checkNumber(playerComponent.playerDojo.buyHpNum) + 1
            end)
        else
            GameUtils.Toast(localize("今日兑换次数已用完"))
        end
    end
end

function StrengthDialog:OnShow()
    ---显示主界面场景元素
    --- @type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            print("self.controller.IsBackOpen =>" , self.controller.IsBackOpen)
            if not self.controller.IsBackOpen then
                self:Capture()    
            end
            self:InitUI()
            if not IsNull(self.MoreButton) then
                KTool.SetActive(self.MoreButton.gameObject, not checkBool(self.hideBtnMore))
            end
            self:FreshUI()
            CfUtils.RefreshTopGoods({Constants.Currency.FreeDiamondId , Constants.Currency.HpExchangeID })
        end)
    end))
    return coWait
end

function StrengthDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self:InitToggleData()
            self:SwitchBtnAction()
            self:StartTimer()
        end)
    end))
    return coWait
end

function StrengthDialog:OnFocus(focus)
    focus = checkBool(focus)
    local value = isNull(self.valueCusOIL) and 400 or self.valueCusOIL
    self.controller:SetSortOrder(focus and value or 0)

    if focus then
        CfUtils.RefreshTopGoods({Constants.Currency.FreeDiamondId , Constants.Currency.HpExchangeID })
    end
end

function StrengthDialog:StartTimer()
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if checkInt(playerComponent.playerDojo.hp) < checkInt(playerComponent.playerDojo.hpLimit) then
        self.triggerTimer = CS.Engine.Modules.CDTimerModule.GetInstance():AddCD(1, function(count)
            local nextRecoveryTime = AppService:GetInstance():GetNextRecoveryTime()
            self.HpTimeText.text = second_toMMSS(nextRecoveryTime)
        end, 86400*30, false, true)
    end
end

function StrengthDialog:FreshHpLimit()
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if not isNull(playerComponent) then
        local playerHPLimit = checkInt(playerComponent.playerDojo.hpLimit)
        local hp = checkInt(playerComponent.playerDojo.hp)
        self.HpLimitText.text = string.format("%d<size=36><color=#A6A6A6>/%d</color></size>" ,hp,playerHPLimit) 
        local nextRecoveryTime = AppService:GetInstance():GetNextRecoveryTime()
        local hpNotFull = hp < playerHPLimit
        local isShowTimer = checkBool(hpNotFull or (checkInt(nextRecoveryTime) > 0))
        KTool.SetActive(self.HpTimeText.transform.parent.gameObject, isShowTimer)
        KTool.SetActive(self.TxtFullType.gameObject, not isShowTimer)
        if isShowTimer then
            self.HpTimeText.text = second_toMMSS(nextRecoveryTime)
        end
    end
end
function StrengthDialog:Capture()
    local effectBg = self.Fuzzy.gameObject:GetComponent(typeof(UIEffectCapturedImage))
    if effectBg then
        effectBg.enabled = true
        effectBg:Capture()
    end
end

function StrengthDialog:OnBackShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        print("self.controller.IsBackOpen2 =>" , self.controller.IsBackOpen)
        if self.controller.IsBackOpen then
            self.co = cs_coroutine.start(function ()
                coroutine.yield(Yielders.GetWaitForSeconds(0.35))
                self:Capture()    
            end)
            -- coroutine.yield()
            -- Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
        end
    end))
    return coWait
end

--- 私有函数 道具变化的事件回调
---然后刷新资源条相关
---@param goodsId number
function StrengthDialog:ChangeStrength(goodsId)
    goodsId = checkNumber(goodsId)
    if goodsId == Constants.Currency.HpId then
        self:FreshUI()---体力变化刷新ui
    end
end

function StrengthDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if self.triggerTimer then
            CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.triggerTimer)
            self.triggerTimer = nil
        end
        Events.RemoveListener(Constants.EventNames.EveryThingChangeEventName, self.__everythingChangeHandler)
        self.controller = nil--luabehaviour 中CSharp对象
        self = nil;
    end))
    return coWait
end

return StrengthDialog